"use client";
import { useEffect, useRef, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import {
  Camera,
  Check,
  FileText,
  ImagePlus,
  LoaderCircle,
  Plus,
  RotateCcw,
  Upload,
} from "lucide-react";
import { useCompanion } from "./context";
import { api } from "./companion";
import { Button, Field, Sheet } from "./ui";
import {
  DOC_NAMES,
  emptyExtraction,
  type AppPayload,
  type AppState,
  type DocKind,
  type DocumentRecord,
  type Extraction,
} from "@/lib/types";

export function DocumentSheet({
  onClose,
  documentId,
}: {
  onClose: () => void;
  documentId?: string;
}) {
  const {
      data: { state: s, role, aiConfigured },
      act,
      busy,
      toast,
    } = useCompanion(),
    client = useQueryClient();
  const existing = s.documents.find((d) => d.id === documentId),
    [doc, setDoc] = useState<DocumentRecord | null>(existing || null),
    [extraction, setExtraction] = useState<Extraction>(existing?.extraction || emptyExtraction()),
    [file, setFile] = useState<File | null>(null),
    [preview, setPreview] = useState(""),
    [working, setWorking] = useState(false),
    [error, setError] = useState(""),
    [manual, setManual] = useState(false),
    [editing, setEditing] = useState(false);
  const camera = useRef<HTMLInputElement>(null),
    album = useRef<HTMLInputElement>(null),
    mounted = useRef(true),
    abort = useRef<AbortController | null>(null);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      abort.current?.abort();
    };
  }, []);
  useEffect(() => {
    if (!file) {
      setPreview("");
      return;
    }
    const url = URL.createObjectURL(file);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [file]);
  const live = doc ? s.documents.find((d) => d.id === doc.id) || doc : null;
  const canApplyArchived =
    !!live?.confirmedAt &&
    !live.applied &&
    ((extraction.kind === "test_order" &&
      [3, 4].includes(s.visit.stage) &&
      extraction.tests.length > 0) ||
      (extraction.kind === "report" && s.visit.stage === 4) ||
      (extraction.kind === "payment" && [4, 6].includes(s.visit.stage)) ||
      (extraction.kind === "appointment" && role === "child"));
  function selectFile(f?: File) {
    if (!f) return;
    if (f.size > 10 * 1024 * 1024) {
      setError("请选择10MB以内的照片。");
      return;
    }
    setFile(f);
    setDoc(null);
    setManual(false);
    setError("");
  }
  async function submit(sample?: DocKind, manualData?: Extraction) {
    if (working) return;
    setWorking(true);
    setError("");
    const form = new FormData();
    if (file && !sample) form.append("image", file);
    if (sample) form.append("sample", sample);
    if (manualData) form.append("extraction", JSON.stringify(manualData));
    abort.current = new AbortController();
    try {
      const result = await api<{ document: DocumentRecord; state: AppState; duplicate: boolean }>(
        "/api/documents",
        { method: "POST", body: form, signal: abort.current.signal },
      );
      if (!mounted.current) return;
      await client.cancelQueries({ queryKey: ["family"] });
      client.setQueryData<AppPayload>(
        ["family"],
        (old) =>
          old && {
            ...old,
            state: result.state.revision >= old.state.revision ? result.state : old.state,
          },
      );
      setDoc(result.document);
      setExtraction(result.document.extraction);
      setManual(false);
      setEditing(false);
      if (result.duplicate) toast("单据已存在，已打开原记录。");
    } catch (e) {
      if (mounted.current && (e as Error).name !== "AbortError") setError((e as Error).message);
    } finally {
      if (mounted.current) setWorking(false);
    }
  }
  const reportTask =
    extraction.kind === "report"
      ? s.visit.tests.find((t) => t.name === extraction.targetName) ||
        (!extraction.targetName && s.visit.tests.length === 1 ? s.visit.tests[0] : undefined)
      : undefined;
  return (
    <Sheet
      title={
        working
          ? "正在处理"
          : live
            ? live.confirmedAt
              ? "单据详情"
              : "核对单据"
            : manual
              ? "补充单据信息"
              : file
                ? "预览照片"
                : "拍下单据"
      }
      onClose={onClose}
      elder={role === "elder"}
    >
      <input
        className="visually-hidden"
        type="file"
        accept="image/*"
        capture="environment"
        ref={camera}
        onChange={(e) => selectFile(e.target.files?.[0])}
        aria-label="拍摄单据"
      />
      <input
        className="visually-hidden"
        type="file"
        accept="image/*"
        ref={album}
        onChange={(e) => selectFile(e.target.files?.[0])}
        aria-label="从相册选择单据"
      />
      {working ? (
        <div className="recognizing">
          <div className="scan-document">
            <FileText size={65} strokeWidth={1.1} />
            <span />
          </div>
          <h3>正在整理单据信息</h3>
          <p>请稍候</p>
          <LoaderCircle size={24} className="spin" />
        </div>
      ) : live ? (
        <div className="form-stack">
          <span className={`status-label ${live.confirmedAt ? "confirmed" : ""}`}>
            {live.confirmedAt ? (
              <>
                <Check size={15} />
                已确认
              </>
            ) : (
              "待确认"
            )}
            {live.provider === "sample"
              ? " · 示例单据"
              : live.provider === "manual"
                ? " · 手动补充"
                : " · 图片识别"}
          </span>
          <div className="card recognition-result">
            <span className="document-placeholder">
              <FileText size={52} strokeWidth={1} />
            </span>
            <div>
              <p>单据类型</p>
              <h3>{extraction.title || DOC_NAMES[extraction.kind]}</h3>
              {extraction.tests.map((t) => (
                <div key={t.name}>
                  <p>检查项目</p>
                  <strong>{t.name}</strong>
                  {t.location && <small>{t.location}</small>}
                </div>
              ))}
              {extraction.medicines.map((m, i) => (
                <div key={i}>
                  <p>药品名称</p>
                  <strong>{m.name}</strong>
                  <small>{m.dose || "每次用量待补充"}</small>
                </div>
              ))}
              {extraction.targetName && <strong>{extraction.targetName}</strong>}
            </div>
          </div>
          {extraction.summary && <p className="recognition-summary">{extraction.summary}</p>}
          {!live.confirmedAt && (
            <p className="field-help">
              {extraction.kind === "receipt"
                ? "保存领取信息后，请在拿到正式报告时确认。"
                : extraction.kind === "prescription"
                  ? "确认后保存为用药草稿，由家人核对。"
                  : extraction.kind === "test_order"
                    ? s.visit.stage === 3 || s.visit.stage === 4
                      ? "确认后添加检查项目。"
                      : "先保存单据，到了接诊后再确认检查安排。"
                    : extraction.kind === "report"
                      ? reportTask
                        ? "确认此项报告已取得。"
                        : "请家人核对报告对应的检查项目。"
                      : extraction.kind === "payment"
                        ? "请确认对应项目已缴费。"
                        : "请对照单据确认信息。"}
            </p>
          )}
          {!live.confirmedAt && reportTask && !reportTask.done && (
            <Button
              secondary
              busy={busy}
              onClick={() => act({ type: "testDone", id: reportTask.id })}
            >
              我已做完这项检查
            </Button>
          )}
          {role === "child" && !live.confirmedAt && (
            <button className="text-link" onClick={() => setEditing(!editing)}>
              {editing ? "收起详细字段" : "核对或修改识别信息"}
            </button>
          )}
          {editing && <ExtractionFields value={extraction} onChange={setExtraction} state={s} />}
          {(!live.confirmedAt || canApplyArchived) && (
            <Button
              busy={busy}
              disabled={!!reportTask && !reportTask.done}
              onClick={async () => {
                if (
                  await act({
                    type: "confirmDocument",
                    id: live.id,
                    ...(role === "child" ? { extraction } : {}),
                  })
                ) {
                  toast("单据已确认");
                  onClose();
                }
              }}
            >
              {canApplyArchived
                ? "补充到就医安排"
                : extraction.kind === "payment"
                  ? "确认已缴费"
                  : "确认信息"}
            </Button>
          )}
          {!live.confirmedAt && (
            <Button
              secondary
              onClick={() => {
                setDoc(null);
                setFile(null);
                setManual(false);
              }}
            >
              重新拍照
            </Button>
          )}
          <details className="disclosure-details">
            <summary>查看单据详情</summary>
            <div className="document-original">
              {live.url && (
                <a href={live.url} target="_blank" rel="noreferrer">
                  <img src={live.url} alt={extraction.title || "单据原图"} />
                </a>
              )}
              <div className="card detail-list">
                {[
                  ["类型", DOC_NAMES[extraction.kind]],
                  ["说明", extraction.notes || "暂无补充"],
                  [
                    "状态",
                    live.confirmedAt
                      ? live.applied
                        ? "已确认并更新安排"
                        : "已保存材料"
                      : "待确认",
                  ],
                ].map(([k, v]) => (
                  <div key={k}>
                    <span>{k}</span>
                    <strong>{v}</strong>
                  </div>
                ))}
              </div>
            </div>
          </details>
        </div>
      ) : manual ? (
        <form
          className="form-stack"
          onSubmit={(e) => {
            e.preventDefault();
            void submit(undefined, extraction);
          }}
        >
          <ExtractionFields value={extraction} onChange={setExtraction} state={s} />
          <Button type="submit">保存信息</Button>
          <Button secondary onClick={() => setManual(false)}>
            返回
          </Button>
        </form>
      ) : file ? (
        <div className="form-stack">
          <div className="photo-preview">
            <img src={preview} alt="待识别的单据照片" />
          </div>
          <p className="panel-intro">请确保单据完整、文字清晰。</p>
          <Button onClick={() => submit()}>识别单据</Button>
          <Button secondary onClick={() => camera.current?.click()}>
            <RotateCcw size={20} />
            重新拍照
          </Button>
          <button
            className="text-link"
            onClick={() => {
              setManual(true);
              setExtraction(emptyExtraction());
            }}
          >
            手动补充信息
          </button>
        </div>
      ) : (
        <div className="form-stack">
          <div className="upload-intro">
            <span className="upload-icon">
              <FileText size={52} strokeWidth={1.2} />
            </span>
            <p>支持检查单、报告和处方。</p>
          </div>
          <Button onClick={() => camera.current?.click()}>
            <Camera size={24} />
            拍摄单据
          </Button>
          <Button secondary onClick={() => album.current?.click()}>
            <ImagePlus size={24} />
            从相册选择
          </Button>
          <details className="disclosure-details sample-picker">
            <summary>使用示例单据</summary>
            <p className="field-help">示例数据用于流程演示。</p>
            <div className="sample-grid">
              {(["test_order", "report", "prescription", "receipt", "payment"] as DocKind[]).map(
                (kind) => (
                  <button key={kind} onClick={() => submit(kind)}>
                    <FileText size={23} />
                    <span>{DOC_NAMES[kind]}</span>
                  </button>
                ),
              )}
            </div>
          </details>
          <button
            className="text-link"
            onClick={() => {
              setManual(true);
              setExtraction(emptyExtraction());
            }}
          >
            手动补充信息
          </button>
          {!aiConfigured && <p className="source-note">可使用示例单据或手动补充。</p>}
        </div>
      )}
      {error && (
        <div className="upload-error" role="alert">
          <p>{error}</p>
          {file && !manual && !working && (
            <button
              className="text-link"
              onClick={() => {
                setManual(true);
                setDoc(null);
              }}
            >
              手动补充信息
            </button>
          )}
        </div>
      )}
    </Sheet>
  );
}
function ExtractionFields({
  value: e,
  onChange,
  state: s,
}: {
  value: Extraction;
  onChange: (v: Extraction) => void;
  state: AppState;
}) {
  function change<K extends keyof Extraction>(key: K, value: Extraction[K]) {
    onChange({ ...e, [key]: value });
  }
  return (
    <div className="form-stack extraction-fields">
      <Field label="单据类型">
        <select
          value={e.kind}
          onChange={(event) => {
            const kind = event.target.value as DocKind;
            onChange({ ...e, kind, title: DOC_NAMES[kind] });
          }}
        >
          {Object.entries(DOC_NAMES).map(([kind, label]) => (
            <option key={kind} value={kind}>
              {label}
            </option>
          ))}
        </select>
      </Field>
      <Field label="单据名称">
        <input required value={e.title} onChange={(ev) => change("title", ev.target.value)} />
      </Field>
      {e.kind === "test_order" && (
        <>
          {e.tests.map((t, i) => (
            <div key={i} className="inset-form">
              <Field label="检查名称">
                <input
                  required
                  value={t.name}
                  onChange={(ev) =>
                    change(
                      "tests",
                      e.tests.map((v, n) => (n === i ? { ...v, name: ev.target.value } : v)),
                    )
                  }
                />
              </Field>
              <Field label="地点">
                <input
                  value={t.location}
                  onChange={(ev) =>
                    change(
                      "tests",
                      e.tests.map((v, n) => (n === i ? { ...v, location: ev.target.value } : v)),
                    )
                  }
                />
              </Field>
            </div>
          ))}
          <button
            type="button"
            className="text-link"
            onClick={() => change("tests", [...e.tests, { name: "", location: "" }])}
          >
            <Plus size={17} />
            添加检查项目
          </button>
        </>
      )}
      {(e.kind === "report" || e.kind === "payment") && (
        <Field label="对应项目">
          <select value={e.targetName} onChange={(ev) => change("targetName", ev.target.value)}>
            <option value="">请核对对应项目</option>
            {s.visit.tests.map((t) => (
              <option value={t.name} key={t.id}>
                {t.name}
              </option>
            ))}
            {e.targetName && !s.visit.tests.some((t) => t.name === e.targetName) && (
              <option>{e.targetName}</option>
            )}
          </select>
        </Field>
      )}
      {e.kind === "payment" && (
        <Field label="费用用途">
          <select
            value={e.paymentFor}
            onChange={(ev) => change("paymentFor", ev.target.value as Extraction["paymentFor"])}
          >
            <option value="unknown">尚未确认</option>
            <option value="test">检查费用</option>
            <option value="medicine">药品费用</option>
          </select>
        </Field>
      )}
      {e.kind === "prescription" && (
        <>
          {e.medicines.map((m, i) => (
            <div key={i} className="inset-form">
              {(
                [
                  ["name", "药品名称"],
                  ["strength", "规格"],
                  ["dose", "每次用量与单位"],
                  ["route", "服用方式"],
                  ["frequency", "频次"],
                  ["instructions", "明确的用法要求"],
                ] as const
              ).map(([key, label]) => (
                <Field key={key} label={label}>
                  <input
                    required={key === "name"}
                    value={m[key]}
                    placeholder="未注明时留空"
                    onChange={(ev) =>
                      change(
                        "medicines",
                        e.medicines.map((v, n) => (n === i ? { ...v, [key]: ev.target.value } : v)),
                      )
                    }
                  />
                </Field>
              ))}
            </div>
          ))}
          <button
            type="button"
            className="text-link"
            onClick={() =>
              change("medicines", [
                ...e.medicines,
                { name: "", strength: "", dose: "", route: "", frequency: "", instructions: "" },
              ])
            }
          >
            <Plus size={17} />
            添加药品
          </button>
        </>
      )}
      {e.kind === "appointment" &&
        (["hospital", "department", "date", "time", "location"] as const).map((key, i) => (
          <Field label={["医院", "科室", "日期", "时段", "地点"][i]} key={key}>
            <input value={e[key]} onChange={(ev) => change(key, ev.target.value)} />
          </Field>
        ))}
      <Field label="补充说明">
        <textarea rows={2} value={e.notes} onChange={(ev) => change("notes", ev.target.value)} />
      </Field>
    </div>
  );
}

src/components/voice.tsx.content:
"use client";
import { useEffect, useRef, useState } from "react";
import { Mic, Send, Volume2 } from "lucide-react";
import { useCompanion } from "./context";
import { Button, Sheet, speak } from "./ui";
import { api } from "./companion";
import type { Action } from "@/lib/schema";
interface RecognitionResult {
  isFinal: boolean;
  [index: number]: { transcript: string };
}
interface RecognitionEvent {
  results: { length: number; [index: number]: RecognitionResult };
}
interface Recognition {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  onresult: ((e: RecognitionEvent) => void) | null;
  onerror: ((e: { error: string }) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
  abort: () => void;
}
type SpeechWindow = Window & {
  SpeechRecognition?: new () => Recognition;
  webkitSpeechRecognition?: new () => Recognition;
};
export function VoiceSheet({ onClose }: { onClose: () => void }) {
  const {
      data: { role },
      busy,
      act,
      toast,
    } = useCompanion(),
    [phase, setPhase] = useState("idle"),
    [text, setText] = useState(""),
    [error, setError] = useState(""),
    [supported, setSupported] = useState(true),
    [answer, setAnswer] = useState<{
      reply: string;
      action: Action | null;
      provider: string;
    } | null>(null);
  const recognition = useRef<Recognition | null>(null),
    transcript = useRef(""),
    alive = useRef(true),
    sendOnEnd = useRef(false),
    sending = useRef(false),
    request = useRef<AbortController | null>(null),
    timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  async function ask(value: string) {
    if (sending.current) return;
    if (!value.trim()) {
      setPhase("idle");
      setError("没有识别到文字，请重试或输入文字。");
      return;
    }
    sending.current = true;
    setPhase("processing");
    setError("");
    request.current = new AbortController();
    try {
      const result = await api<{ reply: string; action: Action | null; provider: string }>(
        "/api/chat",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text: value }),
          signal: request.current.signal,
        },
      );
      if (alive.current) {
        setAnswer(result);
        setPhase("answer");
        speak(result.reply);
      }
    } catch (e) {
      if (alive.current && (e as Error).name !== "AbortError") {
        setError((e as Error).message);
        setPhase("idle");
      }
    } finally {
      sending.current = false;
    }
  }
  function start() {
    const Constructor =
      (window as SpeechWindow).SpeechRecognition ||
      (window as SpeechWindow).webkitSpeechRecognition;
    if (!Constructor) {
      setSupported(false);
      setPhase("idle");
      return;
    }
    recognition.current?.abort();
    window.speechSynthesis?.cancel();
    setText("");
    transcript.current = "";
    setAnswer(null);
    setError("");
    sendOnEnd.current = false;
    const rec = new Constructor();
    recognition.current = rec;
    rec.lang = "zh-CN";
    rec.continuous = true;
    rec.interimResults = true;
    rec.onresult = (e) => {
      const parts = [];
      for (let i = 0; i < e.results.length; i++) parts.push(e.results[i][0].transcript);
      transcript.current = parts.join("");
      if (alive.current) setText(transcript.current);
    };
    rec.onerror = (e) => {
      if (!alive.current) return;
      sendOnEnd.current = false;
      if (timer.current) clearTimeout(timer.current);
      setError(
        e.error === "not-allowed"
          ? "麦克风未获授权，可在下方输入文字。"
          : e.error === "no-speech"
            ? "未检测到语音，请重试。"
            : e.error === "network"
              ? "暂时无法连接语音服务，可输入文字。"
              : "暂时无法识别语音，请重试或输入文字。",
      );
      setPhase("idle");
    };
    rec.onend = () => {
      if (!alive.current) return;
      if (timer.current) clearTimeout(timer.current);
      if (sendOnEnd.current) {
        sendOnEnd.current = false;
        void ask(transcript.current);
      } else setPhase((p) => (p === "listening" ? "idle" : p));
    };
    try {
      rec.start();
      setPhase("listening");
    } catch {
      setError("无法打开麦克风，请重试或输入文字。");
      setPhase("idle");
    }
  }
  function finish() {
    sendOnEnd.current = true;
    recognition.current?.stop();
    setPhase("processing");
    timer.current = setTimeout(() => {
      if (sendOnEnd.current) {
        sendOnEnd.current = false;
        recognition.current?.abort();
        void ask(transcript.current);
      }
    }, 1800);
  }
  useEffect(() => {
    alive.current = true;
    start();
    return () => {
      alive.current = false;
      sendOnEnd.current = false;
      recognition.current?.abort();
      request.current?.abort();
      if (timer.current) clearTimeout(timer.current);
      window.speechSynthesis?.cancel();
    };
  }, []);
  return (
    <Sheet
      title={
        phase === "listening"
          ? "您说，我在听"
          : phase === "processing"
            ? "正在处理"
            : phase === "answer"
              ? "助手回复"
              : "语音输入"
      }
      elder={role === "elder"}
      onClose={onClose}
    >
      <div className="voice-content">
        {phase === "answer" && answer ? (
          <>
            <div className="voice-question">{text}</div>
            <p className="voice-answer">{answer.reply}</p>
            <button className="read-button" onClick={() => speak(answer.reply)}>
              <Volume2 size={22} />
              再听一遍
            </button>
            {answer.provider === "sample" && (
              <p className="source-note">示例助手 · 根据当前安排回答</p>
            )}
            {answer.action && (
              <Button
                busy={busy}
                onClick={async () => {
                  if (await act(answer.action!)) {
                    toast("已更新记录");
                    onClose();
                  }
                }}
              >
                确认
              </Button>
            )}
            <Button
              secondary
              onClick={() => {
                setAnswer(null);
                setPhase("idle");
                setText("");
              }}
            >
              继续提问
            </Button>
          </>
        ) : (
          <>
            <div className={`voice-transcript ${!text ? "placeholder" : ""}`} aria-live="polite">
              {text || (phase === "listening" ? "例如：我接下来该去哪里？" : "请在下方输入问题。")}
            </div>
            {phase === "listening" && (
              <div className="waveform" aria-label="麦克风已打开">
                {[9, 15, 22, 13, 26, 32, 19, 11, 24, 17, 29, 13, 21, 10, 17].map((height, i) => (
                  <span key={i} style={{ height, animationDelay: `${i * 0.08}s` }} />
                ))}
              </div>
            )}
            {phase === "listening" ? (
              <Button onClick={finish}>说完了</Button>
            ) : phase === "processing" ? (
              <Button busy>正在处理</Button>
            ) : (
              <>
                {supported && (
                  <Button secondary onClick={start}>
                    <Mic size={22} />
                    开始说话
                  </Button>
                )}
                <form
                  className="voice-text-form"
                  onSubmit={(e) => {
                    e.preventDefault();
                    void ask(text);
                  }}
                >
                  <label htmlFor="voice-text">
                    {supported ? "也可以输入文字" : "可以用手机键盘上的麦克风输入"}
                  </label>
                  <textarea
                    id="voice-text"
                    value={text}
                    rows={3}
                    placeholder="我接下来该去哪里？"
                    onChange={(e) => {
                      setText(e.target.value);
                      transcript.current = e.target.value;
                    }}
                  />
                  <Button type="submit" disabled={!text.trim()}>
                    <Send size={20} />
                    发送
                  </Button>
                </form>
              </>
            )}
            {error && (
              <p className="form-error" role="alert">
                {error}
              </p>
            )}
            <Button secondary onClick={onClose}>
              取消
            </Button>
          </>
        )}
      </div>
    </Sheet>
  );
}

